// Master Multi-Model Trade Synthesizer (Zero-SQL In-Memory Engine)
// Composite-scoring weights and PROCEED/REVIEW/AVOID thresholds now live
// server-side at POST /compliance/trade-synthesis, not here. This node only
// gathers upstream data and calls it. Previously duplicated as unversioned
// inline JS (GitHub issue #5). Honest aggregation still applies: a missing
// or failed upstream dimension is reported as missing by that endpoint,
// never silently replaced with a fabricated number.
const norm = $('Set — Normalize Trade Intake').first().json;
const hs = $('HTTP — HS Classifier').first().json;
const mkt = $('HTTP — GRU Market Opportunity').first().json;
const anomaly = $('HTTP — XGBoost Trade Anomaly').first().json;
const cpMatch = $('HTTP — Counterparty Matcher').first().json;
const cpRisk = $('HTTP — Trade Risk Model').first().json;
const comp = $('HTTP — CEPA Compliance RAG').first().json;

const hs6 = hs?.hs6 ?? null;
const marketScore = mkt?.summary_table?.[0]?.opportunity_score ?? mkt?.top_recommendations?.[0]?.opportunity_score ?? null;
const destinationRank = mkt?.summary_table?.[0]?.final_rank ?? null;
const anomalyScore = anomaly?.risk?.anomaly_score ?? null;
const riskLevel = anomaly?.risk?.risk_level ?? null;
const cpMatchRaw = cpMatch?.counterparties?.[0] ?? null;
const cpMatchScore = cpMatchRaw?.match_score != null ? cpMatchRaw.match_score * 100 : null;
const cpTrustScore = cpRisk?.risk?.trust_score ?? null;
const complianceScore = typeof comp?.compliance_score === 'number' ? comp.compliance_score : null;
const dutySavedUSD = comp?.tariff?.duty_savings_usd ?? null;
const contractValueUSD = Number(norm.target_price_usd * norm.quantity_kg / 1000) || null;

const synthesis = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://host.docker.internal:8000/compliance/trade-synthesis',
  body: {
    hs6,
    market_score: marketScore,
    anomaly_score: anomalyScore,
    risk_level: riskLevel,
    counterparty_match_score: cpMatchScore,
    counterparty_trust_score: cpTrustScore,
    compliance_score: complianceScore,
  },
  json: true,
});

const missing = synthesis.missing_dimensions;
const compositeScore = synthesis.composite_score;
const recommendation = synthesis.recommendation;
const status = synthesis.status;

const tradeRecord = contractValueUSD ? {
  trade_id: `TRD-${norm.origin_country}-${norm.destination_country}-${Math.round(contractValueUSD / 1000)}K`,
  created_at: new Date().toISOString(),
  status: 'ANALYZED',
  escrow_required_usdc: contractValueUSD,
  overall_score: compositeScore,
  recommendation
} : null;

return [{
  json: {
    status,
    missing_dimensions: missing,
    workflow_name: 'GlobeX AI Master Trade Intelligence Engine',
    execution_timestamp: new Date().toISOString(),
    trade_record: tradeRecord,
    trade_corridor: `${norm.origin_country} ➔ ${norm.destination_country}`,
    commodity: norm.product,
    hs_classification: hs6 !== null ? {
      hs6,
      formatted: hs?.hs_code_formatted ?? null,
      description: hs?.product_description ?? null,
      confidence: hs?.confidence ?? 0
    } : null,
    market_opportunity: marketScore !== null ? {
      destination: norm.destination_country,
      rank: destinationRank,
      score: marketScore,
      top_destinations: mkt?.top_recommendations?.slice(0, 3) ?? []
    } : null,
    trade_anomaly: anomalyScore !== null ? {
      score: anomalyScore,
      risk_level: riskLevel,
      anomaly_type: anomaly?.classification?.anomaly_type ?? null,
      signals: anomaly?.signals ?? []
    } : null,
    counterparty_intelligence: cpMatchScore !== null ? {
      top_exporter: cpMatchRaw?.name ?? null,
      match_score: cpMatchScore,
      trust_score: cpTrustScore,
      risk_level: cpRisk?.risk?.risk_level ?? null,
      counterparty_pool_count: cpMatch?.counterparties?.length ?? 0
    } : null,
    compliance_and_tariffs: complianceScore !== null ? {
      trade_agreement: comp?.tariff?.agreement ?? null,
      preferential_duty: comp?.tariff?.preferential_rate_pct != null ? `${comp.tariff.preferential_rate_pct}%` : null,
      standard_mfn_duty: comp?.tariff?.standard_mfn_rate_pct != null ? `${comp.tariff.standard_mfn_rate_pct}%` : null,
      duty_savings_usd: dutySavedUSD,
      mandatory_documents: comp?.required_documents ?? []
    } : null,
    overall_trade_score: compositeScore,
    recommendation,
    n8n_execution_passed: missing.length === 0
  }
}];

// Synthesize Document Verification Verdict (Zero-SQL)
// Decision logic (OCR-liveness check, compliance threshold, blocking flags)
// now lives server-side at POST /compliance/doc-verdict, not here. This node
// only gathers upstream data and calls it. Previously this exact decision
// tree was duplicated as unversioned, untested inline JS (GitHub issue #5).
const docBody = $('Webhook — Document Uploaded').first().json.body || {};
const ocr = $('HTTP — Document OCR Extract').first().json;
const comp = $('HTTP — Doc Compliance Check').first().json;

const complianceScore = typeof comp.compliance_score === 'number' ? comp.compliance_score : null;
const complianceFlags = Array.isArray(comp.flags) ? comp.flags : [];

const verdict = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://host.docker.internal:8000/compliance/doc-verdict',
  body: {
    ocr_status: ocr.status ?? null,
    ocr_data_source: ocr.data_source ?? null,
    compliance_score: complianceScore,
    compliance_flags: complianceFlags,
  },
  json: true,
});

return [{
  json: {
    status: verdict.status,
    workflow: 'Document OCR & Compliance Verification',
    verification_id: `VER-${Date.now().toString(36).toUpperCase()}`,
    document_type: docBody.document_type || 'COMMERCIAL_INVOICE',
    ocr_status: ocr.status || 'UNKNOWN',
    ocr_data_source: ocr.data_source || 'unknown',
    compliance_score: complianceScore,
    compliance_flags: complianceFlags,
    tariff_framework: comp.tariff?.agreement || null,
    mandatory_docs: comp.required_documents || [],
    cleared_for_shipment: verdict.cleared_for_shipment,
    verified_at: new Date().toISOString()
  }
}];

// Synthesize Marketplace Institutional Buyer Matches
// Real counts only: candidateCount/strongMatchCount now come from the
// backend's actual evaluated pool (see src/api/marketplace_api.py — this
// used to be hardcoded 7420/142, disconnected from any real data).
const rawMatch = $('HTTP — Demand Buyer Match').first().json;
const hasResult = rawMatch && Array.isArray(rawMatch.recommendations);

return [{
  json: {
    status: hasResult ? 'SUCCESS' : 'FAILED',
    workflow: 'Marketplace Buyer Demand Matcher',
    query: rawMatch?.query ?? null,
    candidate_count: rawMatch?.candidateCount ?? null,
    strong_matches: rawMatch?.strongMatchCount ?? null,
    top_buyers: rawMatch?.recommendations ?? [],
    data_source: rawMatch?.data_source ?? null,
    matched_at: new Date().toISOString()
  }
}];

// Trade Creation Response (Zero-SQL demo path)
// Escrow/blockchain integration is DEFERRED — see docs/roadmap/escrow_phase.md
// and the blockchain integration track. This node must never fabricate a
// vault address or claim on-chain state that doesn't exist (a real bug found
// here: it used to generate `0x` + Math.random() hex digits as a fake
// contract address). Real trade persistence goes through POST
// /api/v1/trades once the frontend/n8n caller is wired to it; this response
// shape is kept for backward compatibility with existing workflow consumers.
const b = $('Webhook — Create Trade & Escrow').first().json.body || {};
const tradeId = `TRD-${(b.origin_country || 'IND')}-${(b.destination_country || 'ARE')}-${Math.round((b.contract_value_usd || 550000) / 1000)}K`;

return [{
  json: {
    status: 'TRADE_CREATED',
    trade_id: tradeId,
    escrow_vault: {
      status: 'NOT_IMPLEMENTED_DEFERRED',
      note: 'Financial escrow is not implemented. No vault address, no on-chain custody. See docs/roadmap/escrow_phase.md.',
      collateral_token: 'USDC',
      collateral_amount_usd: b.contract_value_usd || 550000,
      settlement_condition: 'SGS_INSPECTION_PASSED'
    },
    milestones: [
      { milestone: 'ESCROW_FUNDED', percentage: 100, status: 'NOT_APPLICABLE_ESCROW_DEFERRED' },
      { milestone: 'BILL_OF_LADING_VERIFIED', percentage: 0, status: 'LOCKED' },
      { milestone: 'CUSTOMS_RELEASE', percentage: 0, status: 'LOCKED' },
      { milestone: 'FINAL_SETTLEMENT', percentage: 100, status: 'LOCKED' }
    ],
    created_at: new Date().toISOString()
  }
}];

// New Listing Published — Buyer Notification Pipeline
// This node runs after a real POST /api/v1/listings insert (see
// src/api/trades_api.py::create_listing, which calls this webhook
// fire-and-forget). It does not persist anything itself — the DB write
// already happened before this workflow ran — it only surfaces candidate
// buyers for the newly published listing so the exporter isn't left
// waiting on a marketplace refresh to find out if there's demand.
const listing = $('Webhook — Listing Published').first().json.body || {};
const match = $('HTTP — Buyer Match For New Listing').first().json;
const hasResult = match && Array.isArray(match.recommendations);

return [{
  json: {
    status: 'LISTING_PUBLISHED',
    listing_id: listing.id ?? null,
    product_name: listing.product_name ?? null,
    candidate_buyer_count: match?.candidateCount ?? null,
    strong_matches: match?.strongMatchCount ?? null,
    top_buyers: hasResult ? match.recommendations.slice(0, 5) : [],
    data_source: match?.data_source ?? null,
    notified_at: new Date().toISOString()
  }
}];
